const photo = (n, alt, cls = '') => {
    let src = typeof n === 'string'
        ? (n.startsWith('f') ? `assets/images/finishing/image-${n.slice(1)}.webp` : `assets/images/new/image-${n}.webp`)
        : `assets/images/editorial/image-${n}.webp`;
    src = assetLocation(src);
    const metadata = pageImageMetadata[src] || { alt, width: 1024, height: 1024 };
    inventory.push({ filename: src, subject: metadata.alt });
    return `<img class="${cls}" src="${src}" alt="${metadata.alt}" width="${metadata.width}" height="${metadata.height}" loading="lazy">`;
};
